// # for head, generator body, over a protocol parameter: builds as on master;
// # the target refers to the lent step's element (the write reaches the
// # caller's A); fed a container iterator (`iter(xs)`) the step copies the
// # stored tuple and the write lands on the copy,
// # BUGS.md#combinator-tuple-step-copies-record-element
// def gen_head_param(it: Iterator[tuple[A, int32]]) -> Iterator[int32]:
//     for a, n in it:  # tpyc: ok
//         a.v += n
//         yield 1                                                        # -> S_RESUME_0
template <::tpystd::typing::Iterator<std::tuple<A, int32_t>> T_it>
std::expected<int32_t, ::tpy::StopIteration> __gen_gen_head_param<T_it>::__next__() {
    while (true) switch (__state) {
    case S_INITIAL:  // entry
        __state = S_DONE;  // until a yield sets where to resume
        [[fallthrough]];
    case S_RESUME_0:  // after: yield 1
    case S_JOIN_0: {
        __for_r_0.emplace(it.__next__());
        if (!(*__for_r_0).has_value()) {
            __state = S_DONE;
            return ::tpy::make_unexpected(::tpy::StopIteration{});
        }
        __for_tup_48 = &(::tpy::unwrap_ref(*(*__for_r_0)));
        a = &(::tpy::unwrap_ref(::tpy::tuple_elem_ref(std::get<0>((*__for_tup_48)))));
        n = std::get<1>((*__for_tup_48));
        a->v = ::tpy::add_check<int32_t>(a->v, n);
        __state = S_RESUME_0;
        return 1;
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}


